def brute(nv):
    edges=[(i,j) for i in range(nv) for j in range(i+1,nv)]
    res=Counter()
    for mask in range(1<<len(edges)):
        m=bin(mask).count('1')
        adj=[[] for _ in range(nv)]
        for idx,(u,v) in enumerate(edges):
            if mask>>idx&1:
                adj[u].append(v);adj[v].append(u)
        dist=[-1]*nv;dist[0]=0;q=deque([0])
        while q:
            u=q.popleft()
            for v in adj[u]:
                if dist[v]<0:
                    dist[v]=dist[u]+1;q.append(v)
        if -1 in dist: continue
        e=sum(d%2==0 for d in dist)
        if e==nv-e: res[m]+=1
    return res
